function renderLibraryComparison(){let panel=document.querySelector("#library-comparison");if(!panel){panel=document.createElement("section");panel.id="library-comparison";panel.className="library-comparison";document.querySelector("#library-list").before(panel);}const records=store.allWithMetadata().filter(item=>state.libraryCompare.includes(item.persona.meta.persona_id));if(records.length!==2){panel.hidden=true;return;}const result=comparePersonas(records[0].persona,records[1].persona);panel.hidden=false;panel.innerHTML=`<div class="panel-heading horizontal"><div><p class="eyebrow">Saved persona comparison</p><h3>${escapeHtml(records[0].persona.origin.name)} vs ${escapeHtml(records[1].persona.origin.name)}</h3></div><button data-library-action="clear-compare">Clear</button></div><p class="muted">${result.changedSections} changed section${result.changedSections===1?"":"s"}. Expand a section to inspect deterministic field differences.</p>${result.sections.map(section=>`<details><summary>${escapeHtml(section.id)} <span>${section.same?"Same":`${section.differences.length} difference${section.differences.length===1?"":"s"}`}</span></summary>${section.same?`<p class="muted">No canonical differences.</p>`:section.differences.slice(0,12).map(diff=>`<p><strong>${escapeHtml(diff.path)}</strong> · ${escapeHtml(diff.status)}<br><small>${escapeHtml(JSON.stringify(diff.a??"—"))} → ${escapeHtml(JSON.stringify(diff.b??"—"))}</small></p>`).join("")}</details>`).join("")}`;}
function applyLibraryFilters(){renderLibrary();}
function ensureLibraryFilters(){const toolbar=document.querySelector(".library-toolbar");if(!toolbar||toolbar.querySelector("#library-setting-filter"))return;const fields=[["setting","Setting"],["species","Species"],["life_stage","Life stage"],["country","Country"],["job","Occupation"]];for(const [key,title] of fields){const label=document.createElement("label");label.textContent=title;const select=document.createElement("select");select.id=`library-${key}-filter`;select.innerHTML='<option value="">Any</option>';const values=[...new Set(store.all().map(persona=>{const path=key==="job"?"life.job":`foundation.${key}`;return path.split(".").reduce((value,part)=>value?.[part],persona)?.name||"";}).filter(Boolean))].sort();select.innerHTML+=values.map(value=>`<option value="${escapeHtml(value.toLowerCase())}">${escapeHtml(value)}</option>`).join("");select.addEventListener("change",applyLibraryFilters);label.appendChild(select);toolbar.appendChild(label);}}
function applyTagFilter(){const expected=document.querySelector("#library-tags-filter")?.value;const cards=[...document.querySelectorAll("#library-list .library-card")];cards.forEach(card=>{const id=card.querySelector("[data-library-action=\"open\"]")?.dataset.id;const tags=store.libraryMetadata(id).tags.map(tag=>tag.toLowerCase());card.hidden=Boolean(expected&&!tags.includes(expected));});const empty=document.querySelector("#library-list .empty-state");if(expected&&cards.length&&!cards.some(card=>!card.hidden)){if(empty)empty.textContent="No characters match these filters.";else document.querySelector("#library-list").insertAdjacentHTML("beforeend",'<div class="empty-state">No characters match these filters.</div>');}}
function ensureTagFilter(){const toolbar=document.querySelector(".library-toolbar");if(!toolbar||toolbar.querySelector("#library-tags-filter"))return;const label=document.createElement("label");label.textContent="Tag";const select=document.createElement("select");select.id="library-tags-filter";select.innerHTML='<option value="">Any</option>';const tags=[...new Set(store.allWithMetadata().flatMap(({metadata})=>metadata.tags))].sort((a,b)=>a.localeCompare(b));select.innerHTML+=tags.map(value=>`<option value="${escapeHtml(value.toLowerCase())}">${escapeHtml(value)}</option>`).join("");select.addEventListener("change",()=>{applyLibraryFilters();setTimeout(applyTagFilter,0);});label.appendChild(select);toolbar.appendChild(label);}
function addVariantActions(){ensureLibraryFilters();ensureTagFilter();document.querySelectorAll('#library-list button[data-library-action="duplicate"]').forEach(button=>{if(button.parentElement.querySelector('[data-library-action="variant"]'))return;const variant=document.createElement("button");variant.dataset.libraryAction="variant";variant.dataset.id=button.dataset.id;variant.textContent="Create Variant";button.parentElement.insertBefore(variant,button.nextSibling);const compare=document.createElement("button");compare.dataset.libraryAction="compare";compare.dataset.id=button.dataset.id;compare.textContent="Select for comparison";button.parentElement.appendChild(compare);const tags=document.createElement("button");tags.dataset.libraryAction="tags";tags.dataset.id=button.dataset.id;tags.textContent="Edit tags";button.parentElement.appendChild(tags);for(const [action,text] of [["markdown","Markdown"],["txt","TXT"],["reference","Reference"]]){const exportButton=document.createElement("button");exportButton.dataset.libraryAction=`export-${action}`;exportButton.dataset.id=button.dataset.id;exportButton.textContent=text;button.parentElement.appendChild(exportButton);}});renderLibraryComparison();}
new MutationObserver(addVariantActions).observe(document.querySelector("#library-list"),{childList:true});
document.querySelector("#library-view").addEventListener("click",event=>{if(event.target.closest('[data-library-action="clear-compare"]')){state.libraryCompare=[];renderLibraryComparison();}});
document.querySelector("#library-list").addEventListener("click",event=>{const button=event.target.closest("button[data-library-action]");if(!button)return;if(button.dataset.libraryAction==="variant"){event.preventDefault();const variant=store.createVariant(button.dataset.id,"Variant");state.persona=variant;state.controller=new PersonaController(state.library,state.persona);state.dirty=false;state.lastChange="Created variant";render();renderLibrary();}if(button.dataset.libraryAction==="compare"){event.preventDefault();state.libraryCompare=state.libraryCompare.includes(button.dataset.id)?state.libraryCompare.filter(id=>id!==button.dataset.id):[...state.libraryCompare,button.dataset.id].slice(-2);renderLibraryComparison();}if(button.dataset.libraryAction==="clear-compare"){state.libraryCompare=[];renderLibraryComparison();}});
document.querySelector("#library-list").addEventListener("click",event=>{const button=event.target.closest("button[data-library-action]");if(!button)return;if(button.dataset.libraryAction==="tags"){event.preventDefault();event.stopImmediatePropagation();const current=store.libraryMetadata(button.dataset.id).tags.join(", ");const value=window.prompt("Tags, separated by commas:",current);if(value!==null)store.updateMetadata(button.dataset.id,{tags:value.split(",")});renderLibrary();}if(button.dataset.libraryAction==="delete"){event.preventDefault();event.stopImmediatePropagation();if(window.confirm("Delete this saved character? Archive keeps it recoverable.")){store.delete(button.dataset.id);state.libraryCompare=state.libraryCompare.filter(id=>id!==button.dataset.id);renderLibrary();}}},true);
