const label = (value) => value?.name ?? value ?? "—";
function populate(name, entries) { form.elements[name].innerHTML = `<option value="">Random</option>${entries.map((entry) => `<option value="${entry.id}">${entry.name}</option>`).join("")}`; }
function display(value) { if (Array.isArray(value)) return value.map(label).join(", "); if (value && typeof value === "object" && !value.name) return Object.values(value).map(label).join(", "); return label(value); }
function noteChange(label) { state.dirty = true; state.lastChange = label; }
function renderCharacterStatus() { const node=document.querySelector("#character-status"); if(!node)return; if(!state.persona){node.innerHTML="<span>Set a few anchors, then generate a character.</span>";return;} const p=state.persona; const stale=p.state.stale_fields||[]; node.innerHTML=`<strong>${escapeHtml(p.origin.name)}</strong><span>${escapeHtml(p.meta.variance)} · Seed ${escapeHtml(p.meta.seed)}</span><span class="${stale.length?"stale":""}">${stale.length?`${stale.length} stale field${stale.length===1?"":"s"}`:"Current"}</span><span class="${state.dirty?"dirty":""}">${state.dirty?"Unsaved changes":"Saved state"}</span>${state.lastChange?`<span>Last change: ${escapeHtml(state.lastChange)}</span>`:""}`; }
function rows(section, values) { const entries=section==="personality"?Object.entries(values).flatMap(([key,value])=>key==="values"?Object.entries(value).map(([role,item])=>[`values.${role}`,item]):[[key,value]]):Object.entries(values); return entries.filter(([key,value])=>key!=="integration"&&(!key.endsWith(".tension")||value)).map(([key,value]) => { const path=`${section}.${key}`; const locked=state.persona.state.locks[path]; const stale=state.persona.state.stale_fields.includes(path); const title={"values.primary":"Primary Value","values.secondary":"Secondary Value","values.tension":"Value Tension"}[key]||key.replaceAll("_"," "); const inspectPath=section==="appearance"&&key==="surface"?"appearance.surface.hair":path; const alternativePath=section==="interests"&&key==="hobbies"?"interests.hobbies.0":path; const supported=state.controller.alternatives(alternativePath).supported; return `<div class="field"><span class="${stale?"stale":""}">${title}${stale?" ⚠":""}</span><span>${display(value)}</span><span class="field-actions"><button class="icon-button ${locked?"locked":""}" data-action="lock" data-path="${path}">${locked?"Locked":"Lock"}</button><button class="icon-button" data-action="reroll" data-path="${path}" ${locked?"disabled":""}>Reroll</button><button class="icon-button" data-action="inspect" data-path="${inspectPath}">Inspect</button>${supported?`<button class="icon-button" data-action="alternatives" data-path="${alternativePath}">Alternatives</button>`:""}</span></div>`; }).join(""); }
function narrativePanel(integration) { if(!integration)return ""; const entries=[["motivation",integration.motivations?.[0]], ["short-term goal",integration.goals?.short_term], ["long-term goal",integration.goals?.long_term], ["internal tension",integration.tensions?.[0]], ["external pressure",integration.pressures?.[0]], ["relationship hook",integration.relationship_hooks?.[0]], ["arc seed",integration.arc_seeds?.[0]], ["scene hook",integration.scene_hooks?.[0]]].filter(([,item])=>item); return `<section class="narrative-panel"><div class="panel-heading horizontal"><div><p class="eyebrow">Derived narrative</p><h3>Current story state</h3></div><span class="muted">${integration.intensity||"ordinary"} intensity</span></div><div class="narrative-summary"><strong>${integration.goals?.short_term?.text||""}</strong><span>${integration.tensions?.[0]?.text||""}</span></div>${entries.map(([title,item])=>{const path=title==="motivation"?"narrative.integration.motivations.0":title==="short-term goal"?"narrative.integration.goals.short_term":title==="long-term goal"?"narrative.integration.goals.long_term":title==="internal tension"?"narrative.integration.tensions.0":title==="external pressure"?"narrative.integration.pressures.0":title==="relationship hook"?"narrative.integration.relationship_hooks.0":title==="arc seed"?"narrative.integration.arc_seeds.0":"narrative.integration.scene_hooks.0";const locked=state.persona.state.locks[path],stale=state.persona.state.stale_fields.includes(path);return `<details class="narrative-row"><summary><span class="${stale?"stale":""}">${title}${stale?" ⚠":""}</span><span>${item.text}</span></summary><div class="narrative-meta"><small>Domain: ${item.domain||"—"} · Sources: ${(item.sources||[]).join(", ")||"none"}</small><span class="field-actions"><button class="icon-button ${locked?"locked":""}" data-action="lock" data-path="${path}">${locked?"Locked":"Lock"}</button><button class="icon-button" data-action="reroll" data-path="${path}" ${locked?"disabled":""}>Reroll</button></span></div></details>`;}).join("")}</section>`; }
function card(section,title,values,open=false) { return `<details class="persona-card" ${open?"open":""}><summary><span>${title}</span><span class="card-actions"><button class="icon-button" data-action="lock-section" data-section="${section}">Lock card</button><button class="icon-button" data-action="reroll-section" data-section="${section}">Reroll card</button></span></summary><div class="card-body">${rows(section,values)}</div></details>`; }
function render() {
  const p=state.persona; if (p) store.saveWorkspace(p); document.querySelector("#persona-name").textContent=p?.origin?.name||"New Persona"; renderCharacterStatus();
  document.querySelector("#narrative-panel").innerHTML=narrativePanel(p.narrative.integration);
  cards.innerHTML=[card("foundation","Foundation",p.foundation,true),card("origin","Origin",p.origin),card("personality","Personality",p.personality),card("life","Life",p.life),card("interests","Interests",p.interests),card("appearance","Appearance",{surface:p.appearance.surface,clothing_style:p.appearance.clothing_style,signature_outfit:p.appearance.signature_outfit}),card("narrative","Narrative",p.narrative,true),card("character_hook","Character Hook",{text:p.character_hook.text},true)].join("");
  const locks=Object.keys(p.state.locks), stale=p.state.stale_fields, warnings=p.state.warnings;
  const checks=(p.state.coherence_checks||[]).map((check)=>`${check.status==="pass"?"✓":"⚠"} ${check.name}`).join("<br>");
  document.querySelector("#context").innerHTML=`<div class="context-block"><h3>Seed</h3><p>${p.meta.seed}</p></div><div class="context-block"><h3>Locks</h3><p>${locks.length?locks.join(", "):"None — fully random"}</p></div><div class="context-block"><h3>Dependencies</h3><p class="${stale.length?"stale":""}">${stale.length?`${stale.length} field(s) may no longer align.`:"No stale fields."}</p>${stale.length?'<p class="card-actions"><button data-action="regenerate-affected">Regenerate affected</button><button data-action="keep-existing">Keep existing</button></p>':""}</div><div class="context-block"><h3>Character Hook</h3><p><button data-action="reroll-hook">New Direction</button></p></div><div class="context-block"><h3>Data contract</h3><p>Schema ${p.meta.schema_version} · Data ${p.meta.data_version}</p></div><div class="context-block"><h3>Coherence</h3><p class="${warnings.length?"warning":""}">${checks||"All deterministic checks passed."}</p></div><div id="decision-inspector" class="context-block" hidden></div>`;
  status.textContent=state.dirty?"Unsaved":"Saved";
  document.querySelector("#persona-output").textContent=writePersona(p);
  renderReference();
}
function renderReference(){if(!state.persona)return;const mode=document.querySelector("#prompt-mode").value;const visualMode=document.querySelector("#visual-mode").value;const target=document.querySelector("#visual-target")?.value||"generic";const density=document.querySelector("#visual-density")?.value||"standard";const prompts=referencePackage(state.persona,mode);const select=document.querySelector("#prompt-type");const selected=select.value;if(!select.options.length)select.innerHTML=Object.keys(prompts).map((key)=>`<option value="${key}">${key.replaceAll("_"," ")}</option>`).join("");if(selected&&prompts[selected])select.value=selected;const projection=projectVisual(state.persona,visualMode);const contradictions=checkVisualContradictions(projection);const sourceHtml=projection.sources.map((item)=>`<p><strong>${item.path}</strong> · ${item.relevance}<br>${item.reason}</p>`).join("");const inspector=document.querySelector(".projection-inspector");let controls=document.querySelector("#projection-controls");if(!controls){controls=document.createElement("div");controls.id="projection-controls";inspector.insertBefore(controls,document.querySelector("#projection-sources"));}const fields=["wardrobe","activity","expression","pose","environment","camera","lighting"].filter((field)=>projection[field]);controls.innerHTML=fields.map((field)=>{const locked=state.persona.state.visual_locks?.[`${visualMode}.${field}`];return `<div class="field"><span>${field.replaceAll("_"," ")}</span><span>${projection[field]}</span><span class="field-actions"><button class="icon-button ${locked?"locked":""}" data-visual-action="lock" data-visual-field="${field}">${locked?"Locked":"Lock"}</button><button class="icon-button" data-visual-action="reroll" data-visual-field="${field}" ${locked?"disabled":""}>Reroll</button></span></div>`;}).join("");const hasOverrides=Object.keys(state.persona.state.visual_overrides?.[visualMode]||{}).length>0;document.querySelector("#reference-output").textContent=visualMode==="reference"&&!hasOverrides&&target==="generic"&&density==="standard"?prompts[select.value||"master"]:serializeVisual(projection,target,{style:mode,density});document.querySelector("#projection-sources").innerHTML=`${sourceHtml}<p><strong>Negative prompt</strong><br>${negativePrompt(projection)}</p>${contradictions.length?`<p class="warning"><strong>Contradictions</strong><br>${contradictions.map((item)=>item.message).join("<br>")}</p>`:"<p>Contradiction checks passed.</p>"}`;}
function escapeHtml(value){return String(value).replace(/[&<>"]/g,(character)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[character]));}
function renderLibrary(){const records=store.allWithMetadata();const filters=[["setting","foundation.setting"],["species","foundation.species"],["life_stage","foundation.life_stage"],["country","foundation.country"],["job","life.job"]].reduce((result,[key,path])=>{const value=document.querySelector(`#library-${key}-filter`)?.value;if(value)result[path]=value;return result;},{});const controls={query:document.querySelector("#library-search")?.value,view:document.querySelector("#library-view-filter")?.value,sort:document.querySelector("#library-sort")?.value,filters};const items=queryLibrary(records,controls);const list=document.querySelector("#library-list");if(!records.length){list.innerHTML='<div class="empty-state">No saved characters yet. Generate a character in Studio, then save it here.</div>';return;}if(!items.length){const view=controls.view;const message=view==="favorites"?"No favorite characters yet.":view==="archived"?"No archived characters.":"No characters match these filters.";list.innerHTML=`<div class="empty-state">${message}</div>`;return;}list.innerHTML=items.map(({persona:p,metadata:m})=>{const identity=[p.foundation?.species,p.foundation?.life_stage].map(display).join(" · ");const setting=[p.foundation?.setting,p.foundation?.country].map(display).join(" · ");const job=display(p.life?.job);const variant=m.lineage?`<small>Variant of ${escapeHtml(m.lineage.parentPersonaId)}</small>`:"";return `<article class="library-card"><div><p class="eyebrow">${m.archived?"Archived":"Saved character"}</p><h3>${escapeHtml(p.origin.name)}</h3><p class="muted">${escapeHtml(identity)}</p><p class="muted">${escapeHtml(setting)}</p><p>${escapeHtml(job)} ${m.favorite?"· ★ Favourite":""}</p>${m.tags.length?`<p class="library-tags">${m.tags.map(tag=>`<span>${escapeHtml(tag)}</span>`).join("")}</p>`:""}${variant}</div><div class="library-actions"><button data-library-action="open" data-id="${escapeHtml(p.meta.persona_id)}">Open in Studio</button><button data-library-action="favorite" data-id="${escapeHtml(p.meta.persona_id)}" aria-pressed="${m.favorite}">${m.favorite?"Remove favourite":"Add favourite"}</button><button data-library-action="archive" data-id="${escapeHtml(p.meta.persona_id)}">${m.archived?"Unarchive":"Archive"}</button><button data-library-action="duplicate" data-id="${escapeHtml(p.meta.persona_id)}">Duplicate</button><button data-library-action="export" data-id="${escapeHtml(p.meta.persona_id)}">JSON</button><button data-library-action="delete" data-id="${escapeHtml(p.meta.persona_id)}">Delete</button></div></article>`;}).join("");}
function renderDecision(path){const panel=document.querySelector("#decision-inspector");if(!panel||!state.persona)return;const trace=decisionTrace(state.library,state.persona,path);const compatibility=trace.context.compatibility?.map(item=>`${item.field}: ${item.status}`).join(" · ")||trace.context.status||"Not applicable";const dependencies=[...(trace.dependencies.direct||[])];panel.hidden=false;panel.innerHTML=`<div class="panel-heading horizontal"><h3>Decision Inspector</h3><button class="icon-button" data-action="close-inspector">Close</button></div><h4>${path}</h4><p>${escapeHtml(decisionSummary(trace))}</p><p><strong>Source</strong><br>${trace.source.unavailable?"Source information unavailable":`${escapeHtml(trace.source.catalogue)} / ${escapeHtml(trace.source.id||path)}`}</p><p><strong>Context</strong><br>${escapeHtml(compatibility)}${trace.context.relevant?.length?`<br>Relevant: ${escapeHtml(trace.context.relevant.join(", "))}`:""}</p><p><strong>Selection</strong><br>${typeof trace.selection==="string"?trace.selection:`${trace.selection.type} · variance ${trace.selection.variance} · deterministic Yes · fallback ${trace.selection.fallback}`}</p>${trace.pool?.status?`<p><strong>Pool</strong><br>${trace.pool.status}</p>`:`<p><strong>Pool</strong><br>${trace.pool.compatible} compatible of ${trace.pool.total}</p>`}<p><strong>Dependencies</strong><br>${dependencies.length?dependencies.map(escapeHtml).join("<br>"):"No direct dependencies recorded."}</p><p><strong>State</strong><br>Locked: ${trace.state.locked?"Yes":"No"} · Stale: ${trace.state.stale?"Yes":"No"}</p>`;}
function renderAlternatives(path) { const panel=document.querySelector("#decision-inspector"); if(!panel||!state.persona)return; const result=state.controller.alternatives(path); if(!result.supported)return; const impact=dependencyInfo(path).downstream; panel.hidden=false; panel.innerHTML=`<div class="panel-heading horizontal"><h3>Compare alternatives</h3><button class="icon-button" data-action="close-inspector">Close</button></div><p class="eyebrow">${escapeHtml(path)}</p><h4>Current</h4><p class="comparison-current">${escapeHtml(result.current.label)}</p>${impact.length?`<div class="impact-preview"><strong>If you choose an alternative</strong><span>${impact.length} dependent field${impact.length===1?"":"s"} will need review.</span><small>${impact.slice(0,6).map(escapeHtml).join(" · ")}${impact.length>6?" · …":""}</small></div>`:""}<p><strong>Compare with</strong></p>${result.alternatives.map((item)=>`<div class="alternative-option"><strong>${escapeHtml(item.label)}</strong><br><small>${alternativeSummary(item)}${item.context.length?` · ${escapeHtml(item.context.join(" · "))}`:""}</small><br><button class="icon-button" data-action="inspect-alternative" data-path="${path}" data-id="${item.id}">Inspect candidate</button><button class="primary icon-button" data-action="choose-alternative" data-path="${path}" data-id="${item.id}">Choose</button></div>`).join("")}${result.fallback?"<p class=\"muted\">Alternatives use the broadened compatible pool required by the existing fallback path.</p>":""}`; }
function anchorsFromForm(){const values=Object.fromEntries(new FormData(form));const anchors=Object.fromEntries(Object.entries(values).filter(([,value])=>value!==""));if(anchors.age)anchors.age=Number(anchors.age);return anchors;}
document.querySelector("#generate").addEventListener("click",()=>{try{state.persona=generatePersona(state.library,{seed:document.querySelector("#seed").value||Date.now(),mode:document.querySelector("#variance").value,anchors:anchorsFromForm()});state.controller=new PersonaController(state.library,state.persona);noteChange("Generated character");render();forgeEvent("generation",`Generated ${state.persona.origin.name}`);if(hub?.preferences().autoCopy)navigator.clipboard.writeText(document.querySelector("#reference-output").textContent).catch(()=>{status.textContent="Generated · clipboard unavailable";});}catch(error){status.textContent="Generation failed";document.querySelector("#context").innerHTML=`<p class="warning">${error.message}</p>`;}});
document.addEventListener("click",(event)=>{const button=event.target.closest("button[data-action]");if(!button||!state.controller)return;event.preventDefault();event.stopPropagation();const action=button.dataset.action;if(action==="lock"){state.controller.toggleLock(button.dataset.path);noteChange(`${button.dataset.path} lock changed`);}if(action==="reroll"){state.controller.rerollField(button.dataset.path);noteChange(`Rerolled ${button.dataset.path}`);}if(action==="inspect"){state.inspectorTrigger=button;state.inspectorPath=button.dataset.path;return renderDecision(button.dataset.path);}if(action==="alternatives"){state.inspectorTrigger=button;state.inspectorPath=button.dataset.path;return renderAlternatives(button.dataset.path);}if(action==="choose-alternative"){if(state.controller.chooseAlternative(button.dataset.path,button.dataset.id)){noteChange(`Changed ${button.dataset.path}`);render();}return;}if(action==="inspect-alternative"){state.inspectorTrigger=button;state.inspectorPath=button.dataset.path;return renderDecision(button.dataset.path);}if(action==="close-inspector"){document.querySelector("#decision-inspector").hidden=true;const trigger=[...document.querySelectorAll("button[data-action]")].find(item=>item.dataset.path===state.inspectorPath&&(item.dataset.action==="inspect"||item.dataset.action==="alternatives"));setTimeout(()=>{(trigger||state.inspectorTrigger)?.focus();},0);return;}if(action==="lock-section"){state.controller.toggleSection(button.dataset.section);noteChange(`${button.dataset.section} locks changed`);}if(action==="reroll-section"){state.controller.rerollSection(button.dataset.section);noteChange(`Rerolled ${button.dataset.section}`);}if(action==="regenerate-affected"){state.controller.regenerateAffected();noteChange("Regenerated affected fields");}if(action==="keep-existing"){state.controller.keepExisting();noteChange("Kept existing fields");}if(action==="reroll-hook"){state.controller.rerollHook();noteChange("Changed character hook");}render();});
