// Cast/Group management completion surface: enriches the existing project detail without embedding records.
function renderCollectionManagement(projectId) {
  const project = projectStore.open(projectId), detail = document.querySelector("#project-detail"); if (!project || !detail) return;
  for (const [storeObj, label, kind] of [[castStore, "Casts", "cast"], [groupStore, "Groups", "group"]]) {
    const id = `project-${kind}-management`, old = detail.querySelector(`#${id}`); old?.remove();
    const items = storeObj.all().filter(item => item.projectRef?.id === projectId), section = document.createElement("section"); section.id = id; section.className = "output-group";
    section.innerHTML = `<h3>${label}</h3>${items.length ? items.map(item => `<div class="field"><span><strong>${escapeHtml(item.name)}</strong> · ${item.personaRefs.length} member(s)</span><button data-collection-action="edit" data-kind="${kind}" data-collection-id="${escapeHtml(item.id)}">Edit</button><button data-collection-action="members" data-kind="${kind}" data-collection-id="${escapeHtml(item.id)}">Manage members</button><button data-collection-action="delete" data-kind="${kind}" data-collection-id="${escapeHtml(item.id)}">Delete</button></div>`).join("") : '<p class="muted">No collections yet.</p>'}<button data-collection-action="create" data-kind="${kind}">Create ${label.slice(0,-1)}</button>`;
    detail.appendChild(section);
  }
  const relationshipSection=document.createElement("section"); relationshipSection.id="project-relationship-management"; relationshipSection.className="output-group"; const relationships=relationshipStore.all().filter(r=>r.projectRef?.id===projectId), names=new Map(store.all().map(p=>[p.meta?.persona_id,p.origin?.name||p.meta?.persona_id])); relationshipSection.innerHTML=`<h3>Relationships</h3>${relationships.length?relationships.map(r=>`<div class="field"><span>${escapeHtml(names.get(r.sourceRef?.id)||r.sourceRef?.id||"Missing")} ${r.direction==="reverse"?"←":"→"} ${escapeHtml(r.type)} ${escapeHtml(names.get(r.targetRef?.id)||r.targetRef?.id||"Missing")}</span><button data-relationship-action="edit" data-id="${escapeHtml(r.id)}">Edit</button><button data-relationship-action="delete" data-id="${escapeHtml(r.id)}">Delete</button></div>`).join(""):'<p class="muted">No relationships yet.</p>'}<button data-relationship-action="create" data-project-id="${escapeHtml(projectId)}">Create Relationship</button>`; detail.appendChild(relationshipSection);
}
document.addEventListener("click",event=>{const button=event.target.closest("[data-relationship-action]");if(!button)return;const action=button.dataset.relationshipAction;if(action==="create"){const projectId=button.dataset.projectId,people=store.allWithMetadata(),source=window.prompt(`Source persona ID:\n${people.map(r=>r.persona.meta.persona_id+" — "+r.persona.origin.name).join("\n")}`),target=window.prompt("Target persona ID:"),type=window.prompt("Relationship type (friend, parent, mentor, manager, etc.):","friend");if(source&&target&&type){try{const r=relationshipStore.create({projectRef:{type:"project",id:projectId},sourceRef:{type:"persona",id:source.trim()},targetRef:{type:"persona",id:target.trim()},type:type.trim()});const p=projectStore.open(projectId);projectStore.update(projectId,{relationshipRefs:[...p.relationshipRefs,{type:"relationship",id:r.id}]});}catch(error){alert(error.message);}}renderCollectionManagement(projectId);}if(action==="edit"){const r=relationshipStore.open(button.dataset.id),description=window.prompt("Description:",r?.description||"");if(r)relationshipStore.update(r.id,{description});renderCollectionManagement(document.querySelector("#project-detail")?.dataset.projectId);}if(action==="delete"){const r=relationshipStore.open(button.dataset.id);if(r&&window.confirm("Delete relationship?")){relationshipStore.delete(r.id);const p=projectStore.open(document.querySelector("#project-detail")?.dataset.projectId);if(p)projectStore.update(p.id,{relationshipRefs:p.relationshipRefs.filter(ref=>ref.id!==r.id)});}renderCollectionManagement(document.querySelector("#project-detail")?.dataset.projectId);}},true);
document.addEventListener("click", event => {
  const opened = event.target.closest("button[data-project-action=\"open\"]"); if (opened) { const panel = document.querySelector("#project-detail"); if (panel) { panel.dataset.projectId = opened.dataset.id; setTimeout(() => renderCollectionManagement(opened.dataset.id), 0); } }
  const button = event.target.closest("[data-collection-action]"); if (!button) return; const kind = button.dataset.kind, storeObj = kind === "group" ? groupStore : castStore, projectId = document.querySelector("#project-detail")?.dataset.projectId; if (!projectId) return;
  if (button.dataset.collectionAction === "create") { const name = window.prompt(`${kind === "group" ? "Group" : "Cast"} name:`); if (name?.trim()) { const item = storeObj.create({ name: name.trim(), projectRef: { type: "project", id: projectId } }); const project = projectStore.open(projectId); projectStore.update(projectId, { [`${kind}Refs`]: [...project[`${kind}Refs`], { type: kind, id: item.id }] }); } }
  if (button.dataset.collectionAction === "edit") { const item = storeObj.open(button.dataset.collectionId), name = window.prompt("Name:", item?.name || ""); if (item && name?.trim()) storeObj.update(item.id, { name: name.trim() }); }
  if (button.dataset.collectionAction === "members") { const item = storeObj.open(button.dataset.collectionId), people = store.allWithMetadata(), choice = window.prompt(`Enter persona ID to toggle membership:\n${people.map(r => `${r.persona.meta.persona_id} — ${r.persona.origin.name}`).join("\n")}`); if (item && choice?.trim()) { const id = choice.trim(); item.personaRefs.some(ref => ref.id === id) ? storeObj.removePersona(item.id, id) : storeObj.addPersona(item.id, id); } }
  if (button.dataset.collectionAction === "delete") { const item = storeObj.open(button.dataset.collectionId); if (item && window.confirm(`Delete ${item.name}? Personas will be preserved.`)) { storeObj.delete(item.id); const project = projectStore.open(projectId); projectStore.update(projectId, { [`${kind}Refs`]: project[`${kind}Refs`].filter(ref => ref.id !== item.id) }); } }
  renderCollectionManagement(projectId);
}, true);
hub = initControlCentre({
  settings: () => state.library?.settings || [],
  personas: () => store.all(),
  personaLibrary: () => store.browserData().personaLibrary,
  projects: () => projectStore.all(), casts: () => castStore.all(), groups: () => groupStore.all(), relationships: () => relationshipStore.all(),
  browserData: () => ({...store.browserData(),...projectStore.browserData(),...sceneStore.browserData(),...castStore.browserData(),...groupStore.browserData(),...relationshipStore.browserData()}),
  importBrowserData: snapshot => { const result=store.importBrowserData(snapshot);const projects=projectStore.importBrowserData(snapshot,new Set(store.all().map(p=>p.meta?.persona_id).filter(Boolean)),{personaMap:result.idMap});const casts=castStore.importBrowserData(snapshot,{personaMap:result.idMap,projectMap:projects.idMap});const groups=groupStore.importBrowserData(snapshot,{personaMap:result.idMap,projectMap:projects.idMap});const relationships=relationshipStore.importBrowserData(snapshot,{personaMap:result.idMap,projectMap:projects.idMap});const scenes=sceneStore.importBrowserData(snapshot,{personaMap:result.idMap,projectMap:projects.idMap});for(const project of projectStore.all()){const castRefs=project.castRefs.map(ref=>({...ref,id:casts.idMap?.[ref.id]||ref.id}));const groupRefs=project.groupRefs.map(ref=>({...ref,id:groups.idMap?.[ref.id]||ref.id}));const relationshipRefs=project.relationshipRefs.map(ref=>({...ref,id:relationships.idMap?.[ref.id]||ref.id}));const sceneRefs=project.sceneRefs.map(ref=>({...ref,id:scenes.idMap?.[ref.id]||ref.id}));projectStore.update(project.id,{castRefs,groupRefs,relationshipRefs,sceneRefs});}renderLibrary();return {...result,projectsImported:projects.imported,castsImported:casts.imported,groupsImported:groups.imported,relationshipsImported:relationships.imported,scenesImported:scenes.imported}; },
  defaults: preferences => {
    document.querySelector("#variance").value = preferences.mode;
    document.querySelector("#prompt-mode").value = preferences.output;
    if ([...form.elements.setting.options].some(o => o.value === preferences.setting)) form.elements.setting.value = preferences.setting;
  },
  capture: () => ({mode:document.querySelector("#variance").value, output:document.querySelector("#prompt-mode").value, anchors:anchorsFromForm()}),
  apply: preset => {
    form.reset();
    for (const [key,value] of Object.entries(preset.anchors || {})) if (form.elements[key]) form.elements[key].value = value;
    document.querySelector("#variance").value = preset.mode;
    document.querySelector("#prompt-mode").value = preset.output;
    renderReference();
  },
  generate: () => document.querySelector("#generate").click()
});

function applyCharacterDraft(persona, draft, {editing=false}={}) {
  const copy=normalizePersona(persona);
  const setFoundation=(key,value)=>{
    if(value===undefined||value===null||value==="")return;
    let next=value;
    if(key==="setting")next=state.library.settings.find(entry=>entry.id===value);
    if(key==="era")next=state.library.eras.find(entry=>entry.id===value);
    if(key==="country")next=state.library.countries.find(entry=>entry.id===value);
    if(key==="species")next=state.library.species.find(entry=>entry.id===value);
    if(key==="life_stage")next=state.library.lifeStages.find(entry=>entry.id===value);
    if(key==="age")next=Number(value);
    if(next===undefined||next===null||Number.isNaN(next))return;
    const before=copy.foundation[key]?.id??copy.foundation[key],after=next?.id??next;
    if(editing&&before!==after)markStale(copy,`foundation.${key}`);
    copy.foundation[key]=structuredClone(next);
    copy.state.locks[`foundation.${key}`]=true;
  };
  if(editing){setFoundation("age",draft.age);setFoundation("gender",draft.gender);setFoundation("setting",draft.setting);setFoundation("era",draft.era);setFoundation("country",draft.country);setFoundation("species",draft.species);setFoundation("life_stage",draft.life_stage);}
  if(String(draft.name||"").trim()){copy.origin.name=String(draft.name).trim().slice(0,120);copy.state.locks["origin.name"]=true;}
  copy.extensions||={};copy.extensions.promptforge||={};
  copy.extensions.promptforge.characterOverrides={
    appearance:String(draft.appearance||"").trim(),personality:String(draft.personality||"").trim(),background:String(draft.background||"").trim(),occupation:String(draft.occupation||"").trim(),location:String(draft.location||"").trim(),interests:String(draft.interests||"").trim(),currentLife:String(draft.currentLife||"").trim(),references:String(draft.references||"").trim(),exclusions:String(draft.exclusions||"").split(",").map(value=>value.trim()).filter(Boolean)
  };
  if(draft.currentLife!==undefined)copy.extensions.promptforge.continuity=applyContinuityEvent(copy.extensions.promptforge.continuity,{type:"set_current",current:{situation:draft.currentLife}},{at:new Date().toISOString()});
  copy.style_profile=normalizeGenreProfile({genres:Object.entries(draft.genres||{}).map(([id,weight])=>({id,weight:Number(weight)})),exclusions:copy.extensions.promptforge.characterOverrides.exclusions,overrides:{}});
  return copy;
}

initProductShell({
  library:()=>state.library||{},
  personas:()=>store.allWithMetadata(),
  openPersona:id=>store.open(id),
  metadata:id=>store.libraryMetadata(id),
  sceneStore,
  projectStore, castStore, groupStore, relationshipStore, relationshipTypes: RELATIONSHIP_TYPES,
  projectCoordinator,
  createCharacter:draft=>{
    const anchors=Object.fromEntries([["setting",draft.setting],["era",draft.era],["country",draft.country],["species",draft.species],["gender",draft.gender],["life_stage",draft.life_stage],["age",draft.age?Number(draft.age):""]].filter(([,value])=>value!==""&&value!==undefined));
    const project=draft.projectId?projectStore.open(draft.projectId):null;
    const options=project?projectGenerationOptions(project,{seed:draft.seed||Date.now(),anchors,library:state.library}):{seed:draft.seed||Date.now(),mode:"varied",anchors};
    let persona=applyCharacterDraft(generatePersona(state.library,options),draft);
    if(project)persona=attachProjectContext(persona,project,anchors,options.projectInheritance);
    const saved=store.save(persona);if(project)projectStore.addPersona(project.id,saved.meta.persona_id);renderLibrary();forgeEvent("generation",`Created character: ${saved.origin.name}`);return saved;
  },
  updateCharacter:(id,draft)=>{const original=store.open(id);let persona=applyCharacterDraft(original,draft,{editing:true});for(const projectId of Object.keys(persona.extensions?.promptforge?.projectContexts||{})){const project=projectStore.open(projectId);if(!project)continue;for(const field of ["setting","era","country","species"]){const before=original.foundation?.[field]?.id??original.foundation?.[field];if(draft[field]&&draft[field]!==before)persona=updatePersonaProjectOverride(persona,project,field,draft[field]);}}const saved=store.save(persona);renderLibrary();return saved;},
  updateCharacterContinuity:(id,event)=>{const saved=store.updateContinuity(id,event);if(saved)renderLibrary();return saved;},
  updateCharacterIntelligence:(id,intelligence)=>{const persona=store.open(id);if(!persona)return null;persona.extensions.promptforge.characterIntelligence=normalizeCharacterIntelligence(intelligence);const saved=store.save(normalizePersona(persona));renderLibrary();return saved;},
  updateCharacterReferences:(id,references)=>{const persona=store.open(id);if(!persona)return null;persona.extensions.promptforge.references=(Array.isArray(references)?references:[]).map(normalizePurposeReference).filter(Boolean);const saved=store.save(normalizePersona(persona));renderLibrary();return saved;},
  openAdvanced:id=>{if(id){const persona=store.open(id);if(persona){state.persona=persona;state.controller=new PersonaController(state.library,state.persona);state.dirty=false;state.lastChange="Opened from Character Studio";render();}}location.hash="studio";},
  importCharacter:raw=>{const snapshot=Array.isArray(raw?.personas)?raw:{personas:[raw?.persona||raw],personaLibrary:{}};const result=store.importBrowserData(snapshot);const id=Object.values(result.idMap)[0];const persona=store.open(id);if(!persona)throw new Error("The file does not contain a valid persona.");renderLibrary();return persona;}
  ,updateProjectPersonaOverride:(projectId,personaId,field,value)=>{const project=projectStore.open(projectId),persona=store.open(personaId);if(!project||!persona)return null;const entry=(state.library[{setting:"settings",era:"eras",country:"countries",species:"species"}[field]]||[]).find(item=>item.id===value);if(!entry)return null;persona.foundation[field]=structuredClone(entry);persona.state.locks[`foundation.${field}`]=true;markStale(persona,`foundation.${field}`);const saved=store.save(updatePersonaProjectOverride(persona,project,field,value));renderLibrary();return saved;}
});
